function eraseTenantData(tenantId) {
  revokeAccess(tenantId);
  rotateKeys(tenantId);
  scrubIngest(tenantId);
  scrubEnrichment(tenantId);
  scrubAnalytics(tenantId);
  publishTombstones(tenantId);
}
